package com.example.starter.dimming;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 规则1：单次调整后须稳定10分钟方可再调，恰满10分钟允许。
 */
class DimmingStabilityTest extends BaseIntegrationTest {

    @Test
    void firstAdjustmentSucceeds() throws Exception {
        var result = dim("TUN-A-01", "stb-1", 4, "MANUAL");
        assertEquals(200, result.getResponse().getStatus());
        assertEquals(3, body(result).get("fromLevel").asInt());
        assertEquals(4, body(result).get("toLevel").asInt());
        assertEquals(4, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void readjustWithinTenMinutesRejected() throws Exception {
        dim("TUN-A-01", "stb-2a", 4, "MANUAL");
        advanceMinutes(9);
        var rejected = dim("TUN-A-01", "stb-2b", 2, "MANUAL");
        assertEquals(409, rejected.getResponse().getStatus());
        assertEquals("STABILITY_NOT_ELAPSED", body(rejected).get("code").asText());
        assertEquals(4, state("TUN-A-01").get("currentLevel").asInt());
        assertEquals(1, recordCount("TUN-A-01"));
    }

    @Test
    void readjustExactlyAtTenMinutesAllowed() throws Exception {
        dim("TUN-A-01", "stb-3a", 4, "MANUAL");
        advanceMinutes(10);
        var allowed = dim("TUN-A-01", "stb-3b", 2, "MANUAL");
        assertEquals(200, allowed.getResponse().getStatus());
        assertEquals(2, state("TUN-A-01").get("currentLevel").asInt());
        assertEquals(2, recordCount("TUN-A-01"));
    }

    @Test
    void stabilityIsPerCircuit() throws Exception {
        dim("TUN-A-01", "stb-4a", 4, "MANUAL");
        var other = dim("TUN-A-02", "stb-4b", 5, "MANUAL");
        assertEquals(200, other.getResponse().getStatus());
        assertEquals(5, state("TUN-A-02").get("currentLevel").asInt());
    }

    @Test
    void unknownCircuitReturns404() throws Exception {
        var result = dim("NO-SUCH", "stb-5", 4, "MANUAL");
        assertEquals(404, result.getResponse().getStatus());
        assertEquals("CIRCUIT_NOT_FOUND", body(result).get("code").asText());
    }

    @Test
    void invalidLevelRejected() throws Exception {
        var result = mvc.perform(
                org.springframework.test.web.servlet.request.MockMvcRequestBuilders
                        .post("/api/circuits/TUN-A-01/commands")
                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"stb-6\",\"targetLevel\":9,\"source\":\"MANUAL\"}"))
                .andReturn();
        assertEquals(400, result.getResponse().getStatus());
        assertTrue(body(result).get("code").asText().equals("VALIDATION_FAILED"));
    }
}

package com.example.starter.dimming;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 规则2：洞外亮度低于合成阈值立即提升一档并进入过渡曲线；恰等阈值不触发；过渡期间禁止下调。
 */
class BrightnessThresholdTest extends BaseIntegrationTest {

    @Test
    void brightnessEqualToThresholdDoesNotTrigger() throws Exception {
        var result = telemetry("TUN-A-01", "br-1", 500.0, 100);
        assertEquals(200, result.getResponse().getStatus());
        assertEquals("NONE", body(result).get("action").asText());
        assertEquals(3, state("TUN-A-01").get("currentLevel").asInt());
        assertTrue(state("TUN-A-01").get("transitionUntil").isNull());
        assertEquals(0, recordCount("TUN-A-01"));
    }

    @Test
    void brightnessBelowThresholdRaisesOneLevelImmediately() throws Exception {
        var result = telemetry("TUN-A-01", "br-2", 499.0, 100);
        assertEquals(200, result.getResponse().getStatus());
        assertEquals("BRIGHTNESS_RAISE", body(result).get("action").asText());
        assertEquals(4, state("TUN-A-01").get("currentLevel").asInt());
        assertFalse(state("TUN-A-01").get("transitionUntil").isNull());
        assertEquals(1, recordCount("TUN-A-01"));
        assertEquals("BRIGHTNESS", jdbc.queryForObject(
                "SELECT source FROM dimming_record WHERE circuit_code = 'TUN-A-01'",
                String.class));
    }

    @Test
    void brightnessRaiseBypassesStabilityWindow() throws Exception {
        dim("TUN-A-01", "br-3a", 4, "MANUAL");
        advanceMinutes(3);
        var result = telemetry("TUN-A-01", "br-3b", 100.0, 100);
        assertEquals("BRIGHTNESS_RAISE", body(result).get("action").asText());
        assertEquals(5, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void downDimForbiddenDuringTransition() throws Exception {
        telemetry("TUN-A-01", "br-4a", 100.0, 100);
        advanceMinutes(1);
        var rejected = dim("TUN-A-01", "br-4b", 2, "BRIGHTNESS");
        assertEquals(409, rejected.getResponse().getStatus());
        assertEquals("TRANSITION_IN_PROGRESS", body(rejected).get("code").asText());
        assertEquals(4, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void downDimAllowedAfterTransitionAndStability() throws Exception {
        telemetry("TUN-A-01", "br-5a", 100.0, 100);
        advanceMinutes(10);
        var allowed = dim("TUN-A-01", "br-5b", 2, "MANUAL");
        assertEquals(200, allowed.getResponse().getStatus());
        assertEquals(2, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void raiseAtMaxLevelIsNoop() throws Exception {
        dim("TUN-A-01", "br-6a", 5, "MANUAL");
        advanceMinutes(10);
        var result = telemetry("TUN-A-01", "br-6b", 100.0, 100);
        assertEquals("NONE", body(result).get("action").asText());
        assertEquals(5, state("TUN-A-01").get("currentLevel").asInt());
    }
}

package com.example.starter.dimming;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * 规则3：车流量按5分钟滚动窗口更新，窗口内恰为0时降至保底亮度（档位1）。
 */
class TrafficZeroTest extends BaseIntegrationTest {

    @Test
    void zeroTrafficDropsToFloorLevel() throws Exception {
        var result = telemetry("TUN-A-01", "tf-1", 600.0, 0);
        assertEquals(200, result.getResponse().getStatus());
        assertEquals("TRAFFIC_FLOOR", body(result).get("action").asText());
        assertEquals(1, state("TUN-A-01").get("currentLevel").asInt());
        assertEquals("TRAFFIC", jdbc.queryForObject(
                "SELECT source FROM dimming_record WHERE circuit_code = 'TUN-A-01'",
                String.class));
    }

    @Test
    void nonZeroTrafficDoesNotTrigger() throws Exception {
        var result = telemetry("TUN-A-01", "tf-2", 600.0, 5);
        assertEquals("NONE", body(result).get("action").asText());
        assertEquals(3, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void rollingWindowAccumulatesSamplesWithinFiveMinutes() throws Exception {
        telemetry("TUN-A-01", "tf-3a", 600.0, 0);
        // 第一次已为0触发降至保底；换回路验证窗口聚合
        telemetry("TUN-A-02", "tf-3b", 600.0, 0);
        assertEquals(1, state("TUN-A-02").get("currentLevel").asInt());
    }

    @Test
    void rollingWindowMixedSamplesDoNotTrigger() throws Exception {
        telemetry("TUN-A-01", "tf-4a", 600.0, 0);
        // 上一笔已触发保底，重置回路档位验证窗口内混合样本
        jdbc.update("UPDATE circuit SET current_level = 3, last_adjusted_at = NULL WHERE code = 'TUN-A-01'");
        advanceMinutes(3);
        var result = telemetry("TUN-A-01", "tf-4b", 600.0, 10);
        assertEquals("NONE", body(result).get("action").asText());
        assertEquals(3, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void samplesOlderThanFiveMinutesAreExcluded() throws Exception {
        telemetry("TUN-A-01", "tf-5a", 600.0, 8);
        advanceMinutes(6);
        // 窗口内只剩本次0流量样本，旧样本(8)已滚出窗口
        var result = telemetry("TUN-A-01", "tf-5b", 600.0, 0);
        assertEquals("TRAFFIC_FLOOR", body(result).get("action").asText());
        assertEquals(1, state("TUN-A-01").get("currentLevel").asInt());
    }

    @Test
    void zeroTrafficDeferredWithinStabilityWindow() throws Exception {
        dim("TUN-A-01", "tf-6a", 4, "MANUAL");
        advanceMinutes(5);
        var result = telemetry("TUN-A-01", "tf-6b", 600.0, 0);
        assertEquals("NONE", body(result).get("action").asText());
        assertEquals(4, state("TUN-A-01").get("currentLevel").asInt());
        // 稳定期满后再报0流量即降至保底
        advanceMinutes(5);
        var later = telemetry("TUN-A-01", "tf-6c", 600.0, 0);
        assertEquals("TRAFFIC_FLOOR", body(later).get("action").asText());
        assertEquals(1, state("TUN-A-01").get("currentLevel").asInt());
    }
}

